@layer nz.tokens, nz.themes, nz.reset, nz.base, nz.components, nz.patterns, nz.utilities;


@layer nz.components {
  .nz-page-indicator {
    --_nz-page-indicator-dot: var(--nz-border-strong);
    --_nz-page-indicator-current: var(--nz-bg-brand);
    --_nz-page-indicator-chip-bg: var(--nz-bg-subtle);
    --_nz-page-indicator-chip-fg: var(--nz-text-primary);

    display: inline-flex;
    align-items: center;

    &[data-tone='media'] {
      --_nz-page-indicator-dot: color-mix(in srgb, var(--nz-text-on-dark) 50%, transparent);
      --_nz-page-indicator-current: var(--nz-text-on-dark);
      --_nz-page-indicator-chip-bg: var(--nz-bg-code);
      --_nz-page-indicator-chip-fg: var(--nz-text-on-dark);
    }
  }

  .nz-page-indicator-dots {
    display: inline-flex;
    align-items: center;
    gap: var(--nz-space-1-5);
  }

  .nz-page-indicator-dot {
    inline-size: var(--nz-space-1-5);
    block-size: var(--nz-space-1-5);
    border-radius: var(--nz-radius-full);
    background: var(--nz-page-indicator-dot, var(--_nz-page-indicator-dot));
    transition:
      inline-size var(--nz-duration-fast) var(--nz-easing-standard),
      background-color var(--nz-duration-fast) var(--nz-easing-standard);

    &[data-selected] {
      inline-size: var(--nz-space-4);
      background: var(--nz-page-indicator-current, var(--_nz-page-indicator-current));
    }
  }

  .nz-page-indicator-fraction {
    padding-block: var(--nz-space-0-5);
    padding-inline: var(--nz-space-2);
    border-radius: var(--nz-radius-full);
    background: var(--nz-page-indicator-chip-bg, var(--_nz-page-indicator-chip-bg));
    color: var(--nz-page-indicator-chip-fg, var(--_nz-page-indicator-chip-fg));
    font: var(--nz-font-label-m);
    letter-spacing: var(--nz-tracking-label-m);
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
  }

  @media (forced-colors: active) {
    .nz-page-indicator-dot {
      background: GrayText;
    }

    .nz-page-indicator-dot[data-selected] {
      background: CanvasText;
    }

    .nz-page-indicator-fraction {
      border: 1px solid CanvasText;
    }
  }
}
